import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第二十卦 观 风地观 巽上坤下","description":"周易 - 第二十卦 观 风地观 巽上坤下","frontmatter":{"title":"第二十卦 观 风地观 巽上坤下","description":"周易 - 第二十卦 观 风地观 巽上坤下"},"headers":[],"relativePath":"zh/classics/zhouyi/021.md","filePath":"zh/classics/zhouyi/021.md"}'),l={name:"zh/classics/zhouyi/021.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="观" tabindex="-1">观 <a class="header-anchor" href="#观" aria-label="Permalink to “观”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>盥而不荐，有孚□若。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>大观在上，顺而巽，中正以观天下。观，盥而不荐，有孚颙若，下观而化也。观天之神道，而四时不忒，圣人以神道设教，而天下服矣。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>风行地上，观；先王以省方，观民设教。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>童观，小人无咎，君子吝。象 曰：初六童观，小人道也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>窥观，利女贞。象曰：窥观女贞，亦可丑也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>观我生，进退。象曰：观我生，进退；未失道也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>观国之光，利用宾于王。象曰：观国之光，尚宾也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>观我生，君子无咎。象曰：观我生，观民也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>观其生，君子无咎。象曰：观其生，志未平也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
